mapper.select:
select shf.* from stra_his_file shf left join b_marketing_task btbp on shf.batch_number = btbp.batch_number left join b_marketing_task_extend bmte on btbp.id = bmte.task_id left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id where shf.create_time >=#{time}
and bsrc.rule_name_short =#{ruleNumber}
and shf.push_status in
and shf.push_status not in
#{pushStatus}
and shf.status =2 and btbp.monitor_type !=2 order by shf.create_time desc limit 1

select bsrc.rule_name_short from stra_his_file shf left join b_marketing_task btbp on shf.batch_number = btbp.batch_number left join b_marketing_task_extend bmte on btbp.id = bmte.task_id left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id where shf.id in
#{id}
order by shf.create_time desc

select shf.id as fileId, shf.batch_number as batchNumber, bmtut.user_type as userType, bmt.task_number as taskNumber, shf.create_time as taskCreateTime from stra_his_file shf left join b_marketing_task bmt on shf.batch_number = bmt.batch_number left join b_marketing_task_extend bmte on bmte.task_id = bmt.id left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id left join b_marketing_task_user_type bmtut on shf.batch_number = bmtut.batch_number where bsrc.rule_name_short in
#{ruleNameShort}
and shf.api_code =#{apiCode}
and shf.status = 2 order by shf.create_time desc
